        return "pc";
    int kind = Arrays.asList(CLASSES).indexOf(w[1]);
    if (kind < 0)
        return "class";
    int[] regs = new int[3];
    for (int i = 0; i < 3; i++) {
        regs[i] = TraceIO.register(w[i + 2]);
    int n = instructions.size();
